// Renders the page from window.SITE_DATA (data/site.js, generated by scripts/build.py).
(function () {
  "use strict";

  const TZ = "America/Toronto";
  const today = new Intl.DateTimeFormat("en-CA", { timeZone: TZ }).format(new Date()); // YYYY-MM-DD

  const esc = (v) => String(v ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const $ = (sel) => document.querySelector(sel);
  const isTBA = (v) => !v || /^tba$/i.test(String(v).trim());

  // Dates are plain YYYY-MM-DD strings; build them at noon UTC so no timezone shifts the day.
  const asDate = (iso) => new Date(iso + "T12:00:00Z");
  const fmt = (iso, opts) => new Intl.DateTimeFormat("en-US", { timeZone: "UTC", ...opts }).format(asDate(iso));
  const daysUntil = (iso) => Math.round((asDate(iso) - asDate(today)) / 86400000);

  function time12(t) {
    if (isTBA(t)) return "Time TBA";
    const m = /^(\d{1,2}):(\d{2})$/.exec(String(t));
    if (!m) return String(t);
    const h = +m[1];
    return `${((h + 11) % 12) + 1}:${m[2]} ${h < 12 ? "a.m." : "p.m."}`;
  }

  function countdown(iso) {
    const n = daysUntil(iso);
    if (n === 0) return "Today";
    if (n === 1) return "Tomorrow";
    if (n < 14) return `In ${n} days`;
    return `In ${Math.round(n / 7)} weeks`;
  }

  const link = (href, label, cls) =>
    `<a class="chip ${cls || ""}" href="${esc(href)}" target="_blank" rel="noopener">${esc(label)}</a>`;

  // Buttons for a session's materials: Paper and Slides first (uploaded file, else link), then any other files.
  function materials(s) {
    const byLabel = (l) => s.files.find((f) => f.label === l);
    const paper = byLabel("Paper")?.path || s.paper_url;
    const slides = byLabel("Slides")?.path || s.slides_url;
    const others = s.files.filter((f) => f.label !== "Paper" && f.label !== "Slides");
    return [
      paper && link(paper, "Paper"),
      slides && link(slides, "Slides", "slides"),
      ...others.map((f) => link(f.path, f.label)),
    ].filter(Boolean).join("");
  }

  function speakerHTML(s) {
    const name = s.speaker_url && !isTBA(s.speaker)
      ? `<a href="${esc(s.speaker_url)}" target="_blank" rel="noopener">${esc(s.speaker)}</a>`
      : isTBA(s.speaker) ? "Speaker TBA" : esc(s.speaker);
    return name;
  }

  function paperHTML(s, cls) {
    if (isTBA(s.paper)) return `<p class="${cls} tba">Paper to be announced</p>`;
    const co = s.coauthors ? ` <span class="muted">(with ${esc(s.coauthors)})</span>` : "";
    return `<p class="${cls}">${esc(s.paper)}${co}</p>`;
  }

  // Next-up ------------------------------------------------------------------
  function renderNext(sessions) {
    const el = $("#next-card");
    const next = sessions.find((s) => !s.cancelled && s.preseminar.date >= today);
    if (!next) {
      el.outerHTML = `<div class="empty">No upcoming pre-seminars scheduled. Check back soon.</div>`;
      return;
    }
    const pre = next.preseminar;
    const facts = [
      ["Presenter", isTBA(next.presenter) ? "To be assigned" : esc(next.presenter)],
      ["Pre-seminar", `${time12(pre.time)} · ${esc(isTBA(pre.room) ? "Room TBA" : pre.room)}`],
    ];
    if (!isTBA(next.seminar.time) || !isTBA(next.seminar.room)) {
      facts.push(["Seminar", `${fmt(next.date, { month: "short", day: "numeric" })} · ${time12(next.seminar.time)}${isTBA(next.seminar.room) ? "" : " · " + esc(next.seminar.room)}`]);
    }
    if (next.faculty.length) facts.push(["Faculty attending", next.faculty.map(esc).join(", ")]);

    el.innerHTML = `
      <div class="datebox">
        <span class="dow">${fmt(pre.date, { weekday: "long" })}</span>
        <span class="day">${fmt(pre.date, { day: "numeric" })}</span>
        <span class="month">${fmt(pre.date, { month: "long", year: "numeric" })}</span>
        <span class="countdown">${countdown(pre.date)}</span>
      </div>
      <div class="next-body">
        <h3>${speakerHTML(next)}</h3>
        ${next.affiliation ? `<div class="aff">${esc(next.affiliation)}</div>` : ""}
        ${paperHTML(next, "paper-title")}
        <dl class="facts">${facts.map(([k, v]) => `<div><dt>${k}</dt><dd>${v}</dd></div>`).join("")}</dl>
        ${next.notes ? `<p>${esc(next.notes)}</p>` : ""}
        <div class="actions">
          ${materials(next)}
          <a class="btn" href="schedule.ics" download>Add to calendar</a>
        </div>
      </div>`;
  }

  // Schedule -------------------------------------------------------------------
  function termOf(iso) {
    const [y, m] = iso.split("-").map(Number);
    return m >= 9 ? `Fall ${y}` : `Winter–Spring ${y}`;
  }

  function sessionRow(s) {
    const pre = s.preseminar;
    const cls = [s.preseminar.date < today && "past", s.cancelled && "cancelled", s.id === window.__nextId && "next"]
      .filter(Boolean).join(" ");
    // Only mention the pre-seminar when it differs from the defaults shown above the table.
    const d = window.__defaults || {};
    const preNote = [
      pre.date !== s.date && fmt(pre.date, { weekday: "short", month: "short", day: "numeric" }),
      pre.time !== d.time && time12(pre.time),
      pre.room !== d.room && !isTBA(pre.room) && esc(pre.room),
    ].filter(Boolean).join(", ");
    const extra = [
      preNote && `Pre-seminar ${preNote}`,
      s.faculty.length && `Faculty: ${s.faculty.map(esc).join(", ")}`,
      s.notes && esc(s.notes),
    ].filter(Boolean);
    const paper = isTBA(s.paper)
      ? `<span class="tba">TBA</span>`
      : `<span class="title">${esc(s.paper)}</span>${s.coauthors ? ` <span class="muted">(with ${esc(s.coauthors)})</span>` : ""}`;
    const mats = materials(s);
    return `
      <tr class="${cls}" id="s-${esc(s.id)}">
        <td class="c-date">${fmt(s.date, { month: "short", day: "numeric" })}${s.id === window.__nextId ? `<span class="badge">Next</span>` : ""}</td>
        <td class="c-speaker">${speakerHTML(s)}${s.cancelled ? `<span class="badge warn">Cancelled</span>` : ""}</td>
        <td class="c-paper">${paper}${extra.length ? `<span class="extra">${extra.join(" · ")}</span>` : ""}</td>
        <td class="c-presenter">${isTBA(s.presenter) ? `<span class="tba">TBA</span>` : esc(s.presenter)}</td>
        <td class="c-files">${mats || `<span class="tba">—</span>`}</td>
      </tr>`;
  }

  const yearLabel = (y) => y.replace("-", "–");

  function renderSchedule(all, year) {
    const body = $("#session-rows");
    const sessions = all.filter((s) => s.year === year);
    const years = [...new Set(all.map((s) => s.year))].sort().reverse();
    const tabs = $("#years");
    tabs.hidden = years.length < 2;
    tabs.innerHTML = years.map((y) =>
      `<button type="button" data-year="${esc(y)}" aria-pressed="${y === year}">${esc(yearLabel(y))}</button>`).join("");
    tabs.querySelectorAll("button").forEach((b) => b.addEventListener("click", () => renderSchedule(all, b.dataset.year)));

    if (!sessions.length) {
      body.innerHTML = `<tr><td colspan="5" class="empty-row">Nothing scheduled yet.</td></tr>`;
      return;
    }
    let term = "";
    body.innerHTML = sessions.map((s) => {
      const t = termOf(s.date);
      const head = t !== term ? `<tr class="term"><th colspan="5" scope="rowgroup">${t}</th></tr>` : "";
      term = t;
      return head + sessionRow(s);
    }).join("");
  }

  // Resources ------------------------------------------------------------------
  function sizeLabel(n) {
    if (!n) return "";
    return n > 1e6 ? `${(n / 1e6).toFixed(1)} MB` : `${Math.max(1, Math.round(n / 1e3))} KB`;
  }

  function renderResources(cats) {
    const el = $("#resource-list");
    const filled = cats.filter((c) => c.items.length);
    if (!filled.length) {
      el.innerHTML = `<p class="muted">No resources yet.</p>`;
      return;
    }
    el.innerHTML = filled.map((c) => `
      <h3>${esc(c.title)}</h3>
      ${c.description ? `<p class="cat-desc">${esc(c.description)}</p>` : ""}
      <ul>
        ${c.items.map((it) => {
          const meta = [it.ext && `${it.ext.toUpperCase()} ${sizeLabel(it.size)}`.trim(), it.added_by && `added by ${esc(it.added_by)}`].filter(Boolean);
          return `<li><a href="${esc(it.url)}" target="_blank" rel="noopener">${esc(it.title)}</a>${it.description ? ` — ${esc(it.description)}` : ""}${meta.length ? ` <span class="meta">(${meta.join(", ")})</span>` : ""}</li>`;
        }).join("")}
      </ul>`).join("");
  }

  // Site-wide bits ---------------------------------------------------------------
  function renderSite(site, built) {
    document.querySelectorAll("[data-bind]").forEach((el) => {
      const k = el.dataset.bind;
      if (k === "organizer-names" && site.organizers?.length) {
        el.textContent = site.organizers.map((o) => o.name.split(" ")[0]).join(" and ");
      } else if (site[k]) {
        el.textContent = site[k];
      }
    });
    if (site.title) document.title = site.title;
    if (site.announcement) {
      const a = $("#announcement");
      a.querySelector(".wrap").textContent = site.announcement;
      a.hidden = false;
    }
    if (site.organizers?.length) {
      $("#contacts").innerHTML = site.organizers
        .map((o) => `<a href="mailto:${esc(o.email)}">${esc(o.name)}</a>`)
        .join(" or ");
    }
    if (built) $("#built").textContent = `Updated ${fmt(built.slice(0, 10), { month: "short", day: "numeric", year: "numeric" })}.`;
  }

  // Highlight the nav item for the section in view.
  function trackSections() {
    const links = [...document.querySelectorAll(".tabs a")];
    const obs = new IntersectionObserver((entries) => {
      entries.forEach((e) => {
        if (!e.isIntersecting) return;
        links.forEach((a) => a.setAttribute("aria-current", String(a.hash === "#" + e.target.id)));
      });
    }, { rootMargin: "-30% 0px -60% 0px" });
    document.querySelectorAll("main .section").forEach((s) => obs.observe(s));
  }

  const data = window.SITE_DATA;
  if (!data) {
    $("#next-card").innerHTML = `<p class="muted">Could not load the schedule. If you are previewing locally, run <code>python3 scripts/build.py</code> first.</p>`;
    return;
  }
  const sessions = data.sessions || [];
  window.__nextId = (sessions.find((s) => !s.cancelled && s.preseminar.date >= today) || {}).id;
  renderSite(data.site || {}, data.built);
  renderNext(sessions);
  window.__defaults = ((data.site || {}).defaults || {}).preseminar || {};
  const d = window.__defaults;
  $("#pre-defaults").textContent = `Pre-seminars start at ${time12(d.time)}${isTBA(d.room) ? "" : " in " + d.room} unless noted.`;
  // Open on the academic year of the next session, or the most recent year if the season is over.
  const current = (sessions.find((s) => s.id === window.__nextId) || sessions[sessions.length - 1] || {}).year || "";
  document.querySelectorAll('[data-bind="term"]').forEach((el) => { el.textContent = yearLabel(current); });
  renderSchedule(sessions, current);
  renderResources(data.resources || []);
  trackSections();
})();
